// code/Game/Dialog/mod_dialog_vtables.cpp
// Standalone bring-up for the LOCAL MOD LIST — ModDialog + ModDetailsDialog.
//
// Why this file exists
// --------------------
// `code/Game/Dialog/moddialog.cpp` (802 lines) and `moddetailsdialog.cpp` (424
// lines) already contain faithful ports of every implementable slot of these two
// dialogs, but BOTH types sat on the generic 48-slot no-op table generated by
// `UI_DIALOG_STUB(...)` in `ui_dialog_stub_factories.cpp`. Construction allocated
// and zeroed the object, installed StubNop everywhere, and nothing the ports do
// was ever reachable — the classic "ported, registered, unwired" shape
// ([[reference-ported-registered-but-unwired]]).
//
// Retail vtable layout (read out of the exe with read_memory, then each slot
// disassembled — NOT taken from Ghidra's slot naming, which mis-attributes the
// entries past the table's end; the next table starts at 0x14015c8c0, exactly
// 10 slots after 0x14015c870):
//
//   ModDialog          vtable 0x14015c870, object 0xD8
//     +0x00 0x140012a30 ScalarDtor    -> ~ModDialog (0x14006ff00) + MemFree
//     +0x08 0x1400128f0 TypeName      -> returns DAT_1401c5288
//     +0x10 0x1400128e0 Type/TypeId   -> returns DAT_1401c5280
//     +0x18 0x14003a948 Persist       -> thunk [0x140151568] (base DialogInstance)
//     +0x20 0x14006f150 OnOpened      == ModDialog_Slot4   (the mod-list build)
//     +0x28 0x14003a94e OnClosed      -> thunk [0x140151570] (base)
//     +0x30 0x14006e480 OnUpdateLayout-> thunk [0x1401517b0] (base)
//     +0x38 0x14003a990 OnUpdate      -> thunk [0x1401517b8] (base)
//     +0x40 0x14006ed40 OnElementEvent== ModDialog_Slot8   (button dispatch)
//     +0x48 0x14003a954 OnSerSettings -> thunk [0x140151578] (base)
//
//   ModDetailsDialog   vtable 0x14015c670, object 0xC8
//     +0x00 0x140012890 ScalarDtor    -> sets vtable, [0x1401514e8] ~DialogInstance, free
//     +0x08 0x140012780 TypeName
//     +0x10 0x140012770 Type/TypeId
//     +0x18 0x14003a948 Persist       -> base
//     +0x20 0x14006d700 OnOpened      == ModDetailsDialog_Slot4
//     +0x28 0x14003a94e OnClosed      -> base
//     +0x30 0x14003a98a OnUpdateLayout-> base
//     +0x38 0x14003a990 OnUpdate      -> base
//     +0x40 0x14006d6a0 OnElementEvent== ModDetailsDialog_Slot8
//     +0x48 0x14003a954 OnSerSettings -> base
//
// The base-forward slots are resolved by EXPORT NAME, never by the exe dispatch
// slot's stored value — in the static exe those .rdata slots hold the exe-offset
// of the mangled-name STRING, not a Runtime RVA. Calling one as code EXEC-faults
// (the trap already paid for twice, see tool_base_toolui.cpp's comment).
//
// Gating
// ------
// DEFAULT-ON since 2026-09-05 (BANISHED_LIVE_MODDIALOG is in the default-on table);
// set BANISHED_LIVE_MODDIALOG=0 to fall back to the inert no-op slots. Verified
// unattended with BANISHED_AUTOMENU_BUTTON=7 + BANISHED_AUTOMENU_CLICKS (see
// standalone/autostart.cpp): build, toggle, reorder, details, cancel-revert,
// ok-save-reload, and registry persistence across a clean quit.

